"""Write docs/erd-inventory.md from the packaged ERD extracts and the schema.

uv run python tools/erd_inventory.py
"""

import pathlib

from astemia.adapters.db import models
from astemia.adapters.db.staging import extract_dictionary_rows, load_erds, staging_table_name

OUT = pathlib.Path(__file__).parents[1] / "docs" / "erd-inventory.md"


def main() -> None:
    lines = [
        "# ERD inventory (generated)",
        "",
        "Generated by `tools/erd_inventory.py` from `src/astemia/adapters/db/erd/*.json`.",
        "Do not edit by hand.",
        "",
        "## Verbatim staging tables",
        "",
        "| Staging table | ERD entity names | Source ERDs | Fields |",
        "|---|---|---|---|",
    ]
    for e in sorted(load_erds(), key=lambda x: x.key):
        if not e.wide:
            names = ", ".join(e.names)
            sources = ", ".join(s.removesuffix(".json") for s in e.sources)
            lines.append(f"| `{staging_table_name(e)}` | {names} | {sources} | {len(e.fields)} |")
    extracts, fields = extract_dictionary_rows()
    lines += [
        "",
        "## National extracts (field dictionary + JSON rows)",
        "",
        "| Extract code | ERD entity names | Source ERDs | Fields |",
        "|---|---|---|---|",
    ]
    for x in extracts:
        sources = x["source_erd"].replace(".json", "")
        lines.append(f"| `{x['code']}` | {x['source_entities']} | {sources} | {x['field_count']} |")
    renamed = sorted(
        {(f["source_label"], f["label"]) for f in fields if f["source_label"] != f["label"]}
    )
    lines += [
        "",
        "## Renamed labels in the extract dictionary (NIN, Astemia Medical Solutions, medical doctor)",
        "",
        "| ERD label | Stored as |",
        "|---|---|",
    ]
    lines += [f"| {a} | {b} |" for a, b in renamed]
    n_stg = len(models.STAGING_TABLES)
    n_all = len(models.Base.metadata.tables)
    lines += [
        "",
        f"Totals: {n_all} tables ({n_all - n_stg} canonical/platform, {n_stg} staging); "
        f"{len(extracts)} extracts with {len(fields)} dictionary fields.",
        "",
    ]
    OUT.write_text("\n".join(lines))
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()
